# <auto-generated by typra-emitter>
import json

import yaml

from prompty.model import MustacheFormat


def test_load_json_mustacheformat():
    json_data = r"""
    {
      "kind": "mustache"
    }
    """
    data = json.loads(json_data, strict=False)
    instance = MustacheFormat.load(data)
    assert instance is not None
    assert instance.kind == "mustache"


def test_load_yaml_mustacheformat():
    yaml_data = r"""
    kind: mustache

    """
    data = yaml.load(yaml_data, Loader=yaml.FullLoader)
    instance = MustacheFormat.load(data)
    assert instance is not None
    assert instance.kind == "mustache"


def test_roundtrip_json_mustacheformat():
    """Test that load -> save -> load produces equivalent data."""
    json_data = r"""
    {
      "kind": "mustache"
    }
    """
    original_data = json.loads(json_data, strict=False)
    instance = MustacheFormat.load(original_data)
    saved_data = instance.save()
    reloaded = MustacheFormat.load(saved_data)
    assert reloaded is not None
    assert reloaded.kind == "mustache"


def test_to_json_mustacheformat():
    """Test that to_json produces valid JSON."""
    json_data = r"""
    {
      "kind": "mustache"
    }
    """
    data = json.loads(json_data, strict=False)
    instance = MustacheFormat.load(data)
    json_output = instance.to_json()
    assert json_output is not None
    parsed = json.loads(json_output)
    assert isinstance(parsed, dict)


def test_to_yaml_mustacheformat():
    """Test that to_yaml produces valid YAML."""
    json_data = r"""
    {
      "kind": "mustache"
    }
    """
    data = json.loads(json_data, strict=False)
    instance = MustacheFormat.load(data)
    yaml_output = instance.to_yaml()
    assert yaml_output is not None
    parsed = yaml.safe_load(yaml_output)
    assert isinstance(parsed, dict)


def test_load_mustacheformat_invalid():
    """load must reject invalid input instead of silently defaulting."""
    raised = False
    try:
        MustacheFormat.load(object())
    except ValueError:
        raised = True
    assert raised, "Expected invalid input to be rejected"
